<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; const username=ref('buyer'), password=ref('Buyer123!'), error=ref(''), auth=useAuthStore(), router=useRouter(); async function submit(){try{await auth.login(username.value,password.value);router.push('/drafts')}catch{error.value='登录失败，请检查用户名和密码'}}</script>
<template><div class="login"><el-card><h1>采购需求工作台</h1><el-alert v-if="error" :title="error" type="error"/><el-form @submit.prevent="submit"><el-form-item label="用户名"><el-input v-model="username"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" show-password/></el-form-item><el-button type="primary" native-type="submit" style="width:100%">登录</el-button></el-form></el-card></div></template><style scoped>.login{display:grid;min-height:100vh;place-items:center;background:#f3f6fb}.el-card{width:360px}</style>
